<template>
  <div class="bg-gray-800 p-4 rounded-lg shadow-xl text-sm h-[280px] flex flex-col">
    <!-- 標題固定 -->
    <h3 class="text-center text-lg font-bold text-yellow-400 mb-2 border-b border-gray-700 pb-1 flex-shrink-0">
      戰鬥日誌
    </h3>

    <!-- 日誌內容可滾動 -->
    <div ref="logContainer" class="overflow-y-auto flex-1">
      <p v-for="(log, index) in logs" :key="index" :class="getLogClass(log)" class="mb-1">
        {{ log }}
      </p>
    </div>
  </div>
</template>

<script>
export default {
  name: 'GameLog',
  props: {
    logs: {
      type: Array,
      default: () => []
    }
  },
  methods: {
    getLogClass(log) {
      if (log.includes('系統')) return 'text-gray-400';
      if (log.includes('傷害')) return 'text-red-400 font-medium';
      if (log.includes('回復') || log.includes('獲得')) return 'text-green-400 font-medium';
      if (log.includes('玩家回合')) return 'border-t border-green-700';
      if (log.includes('敵人回合')) return 'border-t border-red-700';
      return 'text-gray-300';
    },
    scrollToBottom() {
      const el = this.$refs.logContainer;
      if (el) {
        el.scrollTop = el.scrollHeight;
      }
    }
  },
  watch: {
    logs: {
      handler() {
        this.$nextTick(() => {
          this.scrollToBottom();
        })
      },
      deep: true
    }
  }
}
</script>
