// 出牌與回合系統
// battle.js
import { applyCardEffect, drawCards } from "./utils.js";
import { enemyAI } from "./enemy.js";

// 出牌
export function playCard(player, enemy, card, logFn, showMsg) {
  if (player.gameOver) return;  // 遊戲已結束，不允許出牌
  const cardIndex = player.hand.findIndex(c => c.id == card.id); 
  if ( cardIndex == -1)  {
    console.warn("ID有問題", card.id);
    return;
    }

  if ((card.costAP || 0)> player.ap) {
    showMsg("行動值不足！");
    return;
  }
  if ((card.costMP || 0) > player.mp) {
    showMsg("魔力不足!");
    return;
  }
  if (card.desc.includes('回復')) {
    if (player.hp == player.maxHP) {
      showMsg("生命值已滿");
      return;
    }
  }

  player.ap -= card.costAP || 0;
  player.mp -= card.costMP || 0;

  logFn( player.name + "使用卡牌：" + card.name);

  applyCardEffect(player, enemy, card, logFn);

  player.hand.splice(cardIndex, 1);
  player.discard.push(card);

  console.log("卡牌進入棄牌堆(ID)：", card.id);
}

// 下一回合
export async function nextTurn(player, enemy, logFn) {
    logFn("敵人回合開始");

    enemy.ap = 3;
    enemy.mp = 3;

    // drawCards(enemy, 3);[]
    
    await enemyAI(player, enemy, logFn);
    enemy.buff = 0;
    startPlayerTurn(player, logFn);
}

// 玩家回合開始
export function startPlayerTurn(player, logFn) {
    logFn("玩家回合開始");

    console.log(player.deck);

    // 重置資源
    player.ap = 3;
    player.mp = 3;

    // 抽牌
    drawCards(player, 3);

    console.log(player.hand);
}

// 結束玩家回合
export async function endPlayerTurn(player, enemy, logFn) {
  // 將剩餘手牌放入棄牌堆
  while (player.hand.length > 0) {
    const card = player.hand.pop();

    player.discard.push(card);

    console.log("剩下的卡牌進入棄牌堆(ID)：", card.id);
  }
  player.buff = 0;

  await nextTurn(player, enemy, logFn);
}

