// 工具函式
//utils.js
import { cards } from "../data/card.js";
import { rewards } from "../data/reward.js";

export function initBattle(player, enemy) {
    player.deck = JSON.parse(JSON.stringify(player.baseDeck));
    player.hand = [];
    player.hp = player.maxHP;
    player.buff = 0;
    player.defend = 0;
    player.gameOver = false;

    enemy.deck = JSON.parse(JSON.stringify(enemy.baseDeck));
    enemy.hand = [];
    enemy.hp = enemy.maxHP;
    enemy.buff = 0;
    enemy.defend = 0;
    enemy.gameOver = false;

    shuffle(player.deck);
    shuffle(enemy.deck);
    drawCards(player, 3);
    drawCards(enemy, 3);
}

// 洗牌函式：直接對傳入的陣列進行洗牌
export function shuffle(deck) {
    if (!Array.isArray(deck) || deck.length === 0) {
        return;
    }
    
    for (let i = deck.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [deck[i], deck[j]] = [deck[j], deck[i]];
    }
    console.log("牌已打亂");
}

// 抽牌（自動偵測是否需要洗牌補牌）
export function drawCards(player, amount) {
    console.log("--- 開始抽取", amount, "張卡牌 ---");
    console.log("抽取前牌庫:", player.deck);

    for (let i = 0; i < amount; i++) {
        // --- 檢查和洗牌邏輯 ---
        if (player.deck.length === 0) {
            if (player.discard.length === 0) {
                console.log("沒有牌可以抽了！");
                break;
            }
            
            console.log("牌組沒牌 → 洗棄牌堆");
            
            const idsToShuffle = player.discard.map(item => {
                // 如果 item 是物件，取它的 ID 屬性
                if (typeof item === 'object' && item !== null && item.id) {
                    return item.id;
                }
                // 如果 item 已經是字串 ID，直接返回
                return item;
            }).filter(id => typeof id === 'string'); // 只保留有效的字串 ID

            player.deck.push(...idsToShuffle); // 把有效的 ID 移入牌組
            player.discard.length = 0; // 清空棄牌堆
            
            shuffle(player.deck);
        }

        // --- 抽一張卡 ---
        const cardId = player.deck.shift();
        
        // 檢查卡牌 ID 是否有效
        if (!cardId || typeof cardId !== 'string') {
            console.error(`🚨 錯誤：從牌庫抽出的 ID 無效或非字串，值為: ${cardId}`);
            break;
        }
        
        // 根據 ID 取得卡牌物件
        const cardObj = cards[cardId]; 

        if (!cardObj) {
            console.error(`🚨 錯誤：找不到卡牌 ID ${cardId} 的資料！`);
            break;
        }
        
        // 將卡牌物件的副本加入手牌（這部分您的寫法是正確的）
        player.hand.push({...cardObj});
        
        console.log(`成功抽取: ${cardObj.name || cardId}`);
    }
    
    console.log("抽取後牌庫 (IDs):", player.deck);
    console.log("當前手牌 (Objects):", player.hand);
    console.log("--- 抽取結束 ---");
}

export function discardCard(player, card) {
    const cardId = typeof card === 'object' && card.id ? card.id : card;
    if (cardId) {
        player.discard.push(cardId);
    }
}

// 套用卡牌效果
export function applyCardEffect(player, enemy, card, logFn) {
    console.log(`${player.name} 使用 ${card.name}`);

    switch (card.type) {

        case "attack":
        case "ranged_attack":
        case "magic_attack": {
            let dmg = card.dmg + (player.buff || 0) + (player.attack || 0);

            // 扣護甲
            let armorLoss = Math.min(enemy.defend, dmg);
            enemy.defend -= armorLoss;
            let actualDmg = dmg - armorLoss;

            actualDmg = Math.max(0, actualDmg);

            // 扣 HP\
            if (actualDmg > 0) {
                const hploss = Math.min(actualDmg, enemy.hp);
                enemy.hp -= hploss;
                logFn(`${enemy.name} 受到 ${hploss} 點傷害（剩餘 HP=${enemy.hp}, 護甲=${enemy.defend}）`);
            }
            else {
                logFn(`${player.name} 的攻擊被護甲完全吸收`)
            }
            break;
        }

        case "defend":
        case "magic_defend":
            player.defend += card.def;
            logFn(`${player.name} 獲得 ${card.def} 護甲（目前護甲=${player.defend}）`);
            break;

        case "heal":
            if (player.hp === player.maxHP) {
                logFn(`${player.name} 生命值已滿`);
            } else {
                // 計算實際可回復量
                const healAmount = Math.min(card.heal, player.maxHP - player.hp);

                player.hp += healAmount;

                logFn(`${player.name} 回復 ${healAmount}`);
            }
            break;

        case "buff_attack":
            player.buff = (player.buff || 0) + card.buffDmg;
            logFn(`${player.name} 攻擊力上升 +${card.buffDmg}`);
            break;
    }   
}

export function generateRewards(count = 3) {
    const rewardList = Object.values(rewards);
    const shuffled = rewardList.sort(() => Math.random() - 0.5);
    return shuffled.slice(0, count);
}

export function chooseReward(player, reward) {
  if (reward.type === 'money') player.coin += reward.amount || 0;
  if (reward.type === 'item') player.items = player.items || [];
  if (reward.type === 'item') player.items.push(reward);
  if (reward.type === 'card') player.baseDeck = player.baseDeck || [];
  if (reward.type === 'card') player.baseDeck.push(reward.cardId);
}

export function drinkPowerPotion(player, item) {
    player.buffcount = item.buffcount;
    if (item.id.includes("power")) {
        player.attack += item.power;
        console.log("已加攻擊力");
    }
}

export function finishGameCount(player) {
    if(player.buffcount > 0) {
        player.buffcount--;
        console.log("buffcount" + player.buffcount)
    }
    if(player.buffcount === 0){
        player.attack = player.baseAttack;
    }
}