// 敵人資料
import { reactive } from "vue";

export function enemy() {
    return reactive ({
        name: "低階哥布林",
        maxHP: 30, //最大生命值
        hp: 30, //目前生命值
        ap: 3, //行動力
        mp: 0, //魔力值

        //能力值
        defend: 0, //護甲值
        critRate: 0, //暴擊率
        critDmg: 0, //暴擊傷害

        //卡牌系統
        baseDeck: ["atk_nomal", "atk_nomal", "atk_nomal", "def_shield", "heal_bandage"],
        deck: [], //卡組
        hand: [], //手牌
        discard: [], //棄牌區

        //狀態
        buff: 0, //攻擊增強
        gameOver: false
    });
}